import{_ as d,a0 as e,w as p,s as r,I as t,x as a,a1 as s,A as i,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"Windows 11 的外觀受到了 KDE Plasma 和 GNOME 的啓發嗎？ | LCTT x X-CMD","titleTemplate":false,"description":"Windows 11 的外觀受到了 KDE Plasma 和 GNOME 的啓發嗎？ | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Windows 11 的外觀受到了 KDE Plasma 和 GNOME 的啓發嗎？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Windows 11 的外觀受到了 KDE Plasma 和 GNOME 的啓發嗎？ | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20210626 Windows 11 Look Inspired by KDE Plasma and GNOME","title":"Windows 11 的外觀受到了 KDE Plasma 和 GNOME 的啓發嗎？","tag":"202108","desc":""},"relativePath":"202108/20210626 Windows 11 Look Inspired by KDE Plasma and GNOME.md","filePath":"[post].md"}'),m={name:"202108/20210626 Windows 11 Look Inspired by KDE Plasma and GNOME.md"};function w(u,n,g,E,b,W){const o=e("Link");return p(),r("div",null,[n[21]||(n[21]=t("h1",{id:"windows-11-的外觀受到了-kde-plasma-和-gnome-的啓發嗎",tabindex:"-1"},[a("Windows 11 的外觀受到了 KDE Plasma 和 GNOME 的啓發嗎？ "),t("a",{class:"header-anchor",href:"#windows-11-的外觀受到了-kde-plasma-和-gnome-的啓發嗎","aria-label":"Permalink to “Windows 11 的外觀受到了 KDE Plasma 和 GNOME 的啓發嗎？”"},"​")],-1)),n[22]||(n[22]=t("blockquote",null,[t("p",null,"截圖顯示，微軟即將發佈的 Windows 11 操作系統與我們所心愛的 KDE Plasma 和 GNOME 有許多相似之處。它們到底有多相似呢？我們試着比較了一下。")],-1)),n[23]||(n[23]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/202108/06/103308cfoo3xoz2c002hx2.jpg",alt:""})],-1)),n[24]||(n[24]=t("p",null,[a("我曾記得一句俗話 —— “"),t("ruby",null,[a("優秀者模仿，偉大者剽竊"),t("rt",null,"Good artists copy. Great artists steal")]),a("”。我不認識 Windows 11 背後的設計團隊，但他們似乎很大程度上受到了 Linux 桌面的影響。如果你回顧近幾年來的 Windows 系統外觀 —— 從 Windows XP 到 7，再到 10 —— 整體視覺上都沒有什麼太大的變化，直到今天為止。")],-1)),n[25]||(n[25]=t("p",null,"Windows 操作系統的新版本通常有 5 到 7 年的生命週期。如果你試着回想 Windows 提供給你的個性化選項，你會發現這些選項近幾年來基本都是一致的，甚至包括開始菜單位置、寬度、顏色在內的桌面整體的體驗，一切都沒變過。",-1)),t("p",null,[n[1]||(n[1]=a("但隨着 Windows 11 的全新外觀，這一點終於改變了。讓我帶你看一些我之前所見過的截圖，並且分析一下，它們到底和流行的 Linux ",-1)),s(o,{href:"https://www.debugpoint.com/category/desktop-environment"},{default:i(()=>[...n[0]||(n[0]=[a("桌面環境",-1)])]),_:1}),n[2]||(n[2]=a("（如 KDE Plasma 和 GNOME）有多相似。",-1))]),n[26]||(n[26]=l('<h3 id="windows-11-的外觀受到了-kde-plasma-和-gnome-的啓發" tabindex="-1">Windows 11 的外觀受到了 KDE Plasma 和 GNOME 的啓發？ <a class="header-anchor" href="#windows-11-的外觀受到了-kde-plasma-和-gnome-的啓發" aria-label="Permalink to “Windows 11 的外觀受到了 KDE Plasma 和 GNOME 的啓發？”">​</a></h3><h4 id="開始菜單和任務欄" tabindex="-1">開始菜單和任務欄 <a class="header-anchor" href="#開始菜單和任務欄" aria-label="Permalink to “開始菜單和任務欄”">​</a></h4><p>傳統的開始菜單和任務欄主題在 Windows 11 上有所變化。開始菜單和任務欄圖標位於任務欄中央（默認視圖）。Windows 也在設置中提供了將任務欄圖標和開始菜單移回左側的選項。</p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/06/Windows-11-Start-menu-in-light-mode.jpg" alt="Windows 11 – 淺色模式下的開始菜單"></p><p>整體的佈局方式和默認圖標的色彩讓我想起了 KDE Plasma 的任務欄和啓動器。這些圖標很精緻，並且居中，給你帶來一種類似 GNOME 上 Adwaita 圖標的觀感，而任務欄就更像是 KDE Plasma 的任務欄。</p><p>當你打開開始菜單後，它為你提供不同的圖標和選項的排列方式。此外，當你開始打字時，頂部的搜索選項就會彈出。</p><p>現在，來看看全新設計的 KDE Plasma 啓動器。我知道間距、圖標大小和清晰度並不完全一致，但你可以看到，兩者看起來有多麼驚人的相似。</p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/06/KDE-Plasma-5.22-Launcher-in-Light-mode.jpg" alt="KDE Plasma 5.22 亮色模式下的啓動器"></p>',8)),t("p",null,[n[4]||(n[4]=a("如果你正在使用 GNOME 或 Xfce 桌面，藉助 ",-1)),s(o,{href:"https://gitlab.com/LinxGem33/Arc-Menu"},{default:i(()=>[...n[3]||(n[3]=[a("Arc Menu",-1)])]),_:1}),n[5]||(n[5]=a(" 和一些小修改，你可以讓兩者看上去完全一致。",-1))]),n[27]||(n[27]=l('<p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2020/12/gnomecustomize2020-2-1024x576.jpg" alt="修改過的 Arc Menu"></p><h4 id="窗口裝飾" tabindex="-1">窗口裝飾 <a class="header-anchor" href="#窗口裝飾" aria-label="Permalink to “窗口裝飾”">​</a></h4><p>按照傳統，GNOME 總是用圓角作為標準的窗口裝飾。作為對照，Windows 則一直採用直角作為窗口裝飾 —— 似乎一直都這樣，直到現在為止。嗯，在 Windows 11 中，所有窗口裝飾都是圓角，看起來很好。圓角的概念不是什麼版權專利或者新想法，這就有一個問題了，為什麼現在全都在用圓角？是有什麼隱藏的目的嗎？</p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/06/Rounded-Corners-in-Windows-Explorer-and-Nautilus-1024x716.jpg" alt="Windows 資源管理器和 Nautilus 的圓角"></p><p>哦，還記得 GNOME 的應用程序菜單的小指示器嗎？這些小點提示着這裏到底有多少頁的應用程序。Windows 11 似乎也使用了這種這種思路。</p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/06/Dots-in-paging-1024x468.jpg" alt="標記頁面數量的小點"></p><h4 id="調色盤" tabindex="-1">調色盤 <a class="header-anchor" href="#調色盤" aria-label="Permalink to “調色盤”">​</a></h4><p>Windows 多年來始終有基於“藍色”或其他藍色變體的主題。雖然用户可以自行更改任務欄、開始菜單背景、窗口標題欄顏色，但藉助這個選項，調色板與亮暗模式結合，展示出巨大變化，給 Windows 桌面帶來了更圓滑、迷人的外觀。也許這個靈感源自 Ubuntu、KDE 或者其它風格的調色板。</p><h4 id="暗黑模式" tabindex="-1">暗黑模式 <a class="header-anchor" href="#暗黑模式" aria-label="Permalink to “暗黑模式”">​</a></h4><p>Windows 11 首次官方支持了暗黑模式，或者説是暗色主題。那麼，我就直接在下面放兩張截圖，由大家自己評判。左側是 Windows 11 暗黑模式下的開始菜單，右側是使用了 Breeze Dark 主題的 KDE Plasma。</p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/06/Comparison-of-Windows-11-Start-Menu-and-KDE-Plasma-1024x505.jpg" alt="Windows 11 開始菜單與 KDE Plasma 的比較"></p><h4 id="全新桌面小組件" tabindex="-1">全新桌面小組件 <a class="header-anchor" href="#全新桌面小組件" aria-label="Permalink to “全新桌面小組件”">​</a></h4><p>靈感的啓發從來不會停止。還記得 KDE Plasma 的小組件嗎？其實，這也不是什麼新概念，然而小組件已經出現在 Windows 11。這是全新小組件面板的截圖。你可以添加、移除或者重新排序這些小組件。</p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/06/Widgets-menu-1024x833.jpg" alt="小組件菜單"></p><p>這些只是吸引我眼球的冰山一角。也許 Windows 11 還有許多“靈感”來“啓發”它的外觀。</p><p>但問題來了 —— 為什麼現在是一次推出這些功能和外觀的最佳時機？</p><h3 id="結束語" tabindex="-1">結束語 <a class="header-anchor" href="#結束語" aria-label="Permalink to “結束語”">​</a></h3><p>實話實説，當我第一次看到 Windows 11 的新外觀時，我腦袋裏就浮現出 Breeze Dark 主題的 KDE Plasma。藉助很少量的修改，你可以讓 KDE Plasma 看上去像 Windows 11。這本身就説明了它們兩者是有多麼地相似。</p><p>如果你看向整個桌面操作系統的市場，競爭者只有 Windows、Linux 桌面和 macOS。至今為止，它們的外觀都有明顯的標誌性特徵，例如 macOS 有自己獨一無二的外觀。直到現在，Windows 也有一樣的藍色主題的常規開始菜單，等等。但藉助這些新變化，Windows 為用户提供了更豐富的定製選項，讓它看上去更像 Linux 桌面。</p><p>在我個人看來，Windows 團隊需要一種不同的標誌性特徵，而不是一直從我們心愛的 Linux 桌面獲得“啓發”。</p><p>我不知道未來會發生什麼，但現在看來，“E-E-E” 還在竭盡全力運作。（LCTT 譯註：“E-E-E”是微軟臭名昭著的<ruby>擁抱、擴展再消滅<rt>Embrace, extend, and extinguish</rt></ruby>策略。）</p><p>再會。</p><hr>',23)),t("p",null,[n[7]||(n[7]=a("via: ",-1)),s(o,{href:"https://www.debugpoint.com/2021/06/windows-11-inspiration-linux-kde-plasma/"},{default:i(()=>[...n[6]||(n[6]=[a("https://www.debugpoint.com/2021/06/windows-11-inspiration-linux-kde-plasma/",-1)])]),_:1})]),t("p",null,[n[12]||(n[12]=a("作者：",-1)),s(o,{href:"https://www.debugpoint.com/author/admin1/"},{default:i(()=>[...n[8]||(n[8]=[a("Arindam",-1)])]),_:1}),n[13]||(n[13]=a(" 選題：",-1)),s(o,{href:"https://github.com/lujun9972"},{default:i(()=>[...n[9]||(n[9]=[a("lujun9972",-1)])]),_:1}),n[14]||(n[14]=a(" 譯者：",-1)),s(o,{href:"https://github.com/imgradeone"},{default:i(()=>[...n[10]||(n[10]=[a("imgradeone",-1)])]),_:1}),n[15]||(n[15]=a(" 校對：",-1)),s(o,{href:"https://github.com/wxy"},{default:i(()=>[...n[11]||(n[11]=[a("wxy",-1)])]),_:1})]),t("p",null,[n[18]||(n[18]=a("本文由 ",-1)),s(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...n[16]||(n[16]=[a("LCTT",-1)])]),_:1}),n[19]||(n[19]=a(" 原創編譯，",-1)),s(o,{href:"https://linux.cn/"},{default:i(()=>[...n[17]||(n[17]=[a("Linux中國",-1)])]),_:1}),n[20]||(n[20]=a(" 榮譽推出",-1))])])}const D=d(m,[["render",w]]);export{f as __pageData,D as default};
